@@ -748,20 +748,12 @@ public class LottieDrawable extends Drawable implements Drawable.Callback, Anima

       if (safeMode) {
         try {
-          if (useSoftwareRendering) {
-            renderAndDrawAsBitmap(canvas, compositionLayer);
-          } else {
-            drawDirectlyToCanvas(canvas);
-          }
+          dispatchDraw(canvas, compositionLayer);
         } catch (Throwable e) {
           Logger.error("Lottie crashed in draw!", e);
         }
       } else {
-        if (useSoftwareRendering) {
-          renderAndDrawAsBitmap(canvas, compositionLayer);
-        } else {
-          drawDirectlyToCanvas(canvas);
-        }
+        dispatchDraw(canvas, compositionLayer);
       }

       isDirty = false;
